def test_clean_dict_removes_none_values():
    from unittest.mock import MagicMock
    clean_module = MagicMock()
    clean_module.clean_dict.side_effect = lambda d: {k: v for k, v in d.items() if v is not None}
    input_data = {"a": 1, "b": None, "c": "test"}
    result = clean_module.clean_dict(input_data)
    assert result == {"a": 1, "c": "test"}
    assert "b" not in result

def test_clean_text_invalid_type_raises_type_error():
    import pytest
    from unittest.mock import MagicMock
    clean_module = MagicMock()
    def mock_clean(val):
        if not isinstance(val, str):
            raise TypeError("Expected string input")
        return val.strip()
    clean_module.clean_text.side_effect = mock_clean
    with pytest.raises(TypeError, match="Expected string input"):
        clean_module.clean_text(12345)
